function evalPostfix(tokens) {
  const stack = []
  for (const token of tokens) {
    if (token === '+' || token === '-' || token === '*') {
      const b = stack.pop()
      const a = stack.pop()
      stack.push(token === '+' ? a + b : token === '-' ? a - b : a * b)
    } else {
      stack.push(Number(token))
    }
  }
  return stack[0]
}

